INSERT INTO collection_pages VALUES('ac9029a1b5a40681ee317aab3f812e130f59d9de74a063bf0b978dd3a21f05ac','d43a54e794a06e5583ae8019bff8d0799874d1acfdc8d78d449c2cc211a85a6c','{"hasNext":false,"items":[{"author":{"account":null,"email":"miguel.roldan.ext@essity.com","name":"miguel.roldan"},"authoredDate":"2026-08-05T15:20:30Z","committedDate":"2026-08-05T15:20:30Z","committer":{"account":null,"email":"miguel.roldan.ext@essity.com","name":"miguel.roldan"},"observedAt":"2026-10-09T00:04:18.417Z","repositoryId":1324197828,"sha":"ef332b6920d359eb35fdce223a1f3f8dfbc7dd5e"}],"observedAt":"2026-10-09T00:04:18.417Z","raw":[{"author":null,"comments_url":"https://api.github.com/repos/ElDaiko/POC-MFE/commits/ef332b6920d359eb35fdce223a1f3f8dfbc7dd5e/comments","commit":{"author":{"date":"2026-08-05T15:20:30Z","email":"miguel.roldan.ext@essity.com","name":"miguel.roldan"},"comment_count":0,"committer":{"date":"2026-08-05T15:20:30Z","email":"miguel.roldan.ext@essity.com","name":"miguel.roldan"},"message":"Add initial setup for micro-frontends with Vite and Module Federation\n\n- Created README.md for project overview and setup instructions.\n- Added .gitignore files for both app-principal and app-remota to exclude logs and build artifacts.\n- Configured Oxlint for linting in both applications.\n- Set up basic HTML structure in index.html for both apps.\n- Created package.json and package-lock.json for dependency management in both apps.\n- Implemented Vite configuration for module federation in app-principal.\n- Developed main application structure with React components and styles.\n- Added SVG assets and favicon for branding.\n- Established CSS styles for layout and theming.\n- Included a remote component (BotonMagico) in app-principal to demonstrate micro-frontend functionality.","tree":{"sha":"62ab1d3cff065c6c44c8275332cdd2733c4ccc6f","url":"https://api.github.com/repos/ElDaiko/POC-MFE/git/trees/62ab1d3cff065c6c44c8275332cdd2733c4ccc6f"},"url":"https://api.github.com/repos/ElDaiko/P