INSERT INTO collection_pages VALUES('6ecb8dbd58f24da5a80060b0788ba1ceda641b790255a1c4fd67b7e8b467f9de','e888f4a064203d89439e769b1fe693ad298933c932f3af83efb6447c01407891','{"hasNext":false,"items":[{"author":{"account":{"login":"avinashsah995","providerType":"User"},"email":"avinashsah5555@gmail.com","name":"avinashsah995"},"authoredDate":"2026-08-06T09:08:07Z","committedDate":"2026-08-06T09:08:07Z","committer":{"account":{"login":"avinashsah995","providerType":"User"},"email":"avinashsah5555@gmail.com","name":"avinashsah995"},"observedAt":"2026-10-09T00:04:54.063Z","repositoryId":1324978168,"sha":"edc44599f60b9eb5be7588bbfee3cff655d0e19e"}],"observedAt":"2026-10-09T00:04:54.063Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/121078730?v=4","events_url":"https://api.github.com/users/avinashsah995/events{/privacy}","followers_url":"https://api.github.com/users/avinashsah995/followers","following_url":"https://api.github.com/users/avinashsah995/following{/other_user}","gists_url":"https://api.github.com/users/avinashsah995/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/avinashsah995","id":121078730,"login":"avinashsah995","node_id":"U_kgDOBzeDyg","organizations_url":"https://api.github.com/users/avinashsah995/orgs","received_events_url":"https://api.github.com/users/avinashsah995/received_events","repos_url":"https://api.github.com/users/avinashsah995/repos","site_admin":false,"starred_url":"https://api.github.com/users/avinashsah995/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/avinashsah995/subscriptions","type":"User","url":"https://api.github.com/users/avinashsah995","user_view_type":"public"},"comments_url":"https://api.github.com/repos/avinashsah995/mfe-contracts/commits/edc44599f60b9eb5be7588bbfee3cff655d0e19e/comments","commit":{"author":{"date":"2026-08-06T09:08:07Z","email":"avinashsah5555@gmail.com","name":"avinashsah995"},"comment_count":0,"committer":{"date":"2026-08-06T09:08:07Z","email":"avinashsah5555@gmail.com","name":"avinashsah995"},"message":"feat: initial release of shared MFE TypeScript contracts (v0.1.0)\n\nIntroduce @avinash995/mfe-contracts as a types-only package for the\nNovaMart micro frontends, with no React, Zustand, or UI dependencies.\n\nShared domain types:\n- Product (id, name, price, description, category, image)\n- CartItem (Product extended with quantity)\n- User (id, name, email)\n\nOptional event stubs for loose-coupled notifications (e.g. analytics):\n- MFE_EVENTS constants (product viewed, cart opened, user logged in,\n  checkout started)\n- Matching *EventDetail types for each event payload\n\nPackage and tooling:\n- ESM package layout with exports, types entry, and dist-only publish\n- TypeScript 6 build (strict, declarations, source maps)\n- npm scripts: build, lint, pack:check, prepublishOnly\n- GitHub Actions CI (install, lint, build, pack check on Node 22)\n- README, CHANGELOG (Keep a Changelog / SemVer), and .gitignore","tree":{"sha":"8137093d326380aa6ccd835ac2e01e090d69601a","url":"https://api.github.com/repos/avinashsah995/mfe-contracts/git/trees/8137093d326380aa6ccd835ac2e01e090d69601a"},"url":"https://api.github.com/repos/avinashsah995/mfe-contracts/git/commits/edc44599f60b9eb5be7588bbfee3cff655d0e19e","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/121078730?v=4","events_url":"https://api.github.com/users/avinashsah995/events{/privacy}","followers_url":"https://api.github.com/users/avinashsah995/followers","following_url":"https://api.github.com/users/avinashsah995/following{/other_user}","gists_url":"https://api.github.com/users/avinashsah995/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/avinashsah995","id":121078730,"login":"avinashsah995","node_id":"U_kgDOBzeDyg","organizations_url":"https://api.github.com/users/avinashsah995/orgs","received_events_url":"https://